use destiny_activity_service::ActivityService;use destiny_auth_service::AuthService;use destiny_inventory_service::InventoryService;use destiny_network::{Packet,PacketLogger};use destiny_runtime_core::Runtime;use destiny_world_service::WorldService;use std::sync::Arc;use std::time::Instant;
#[derive(Default,Debug,Clone)]pub struct Telemetry{pub request_log:Vec<String>,pub service_timing_ms:Vec<(String,u128)>,pub packet_traces:Vec<String>,pub session_history:Vec<String>}
pub struct ServerRuntime{pub network:NetworkLayer,pub auth:AuthService,pub inventory:InventoryService,pub activities:ActivityService,pub world:WorldService,pub telemetry:Telemetry}
pub struct NetworkLayer{pub log:destiny_network::MemoryPacketLog}impl Default for NetworkLayer{fn default()->Self{Self{log:Default::default()}}}
pub enum DispatchResult{Accepted,UnknownOpcode,Rejected(String)}
impl ServerRuntime{pub fn new(runtime:Arc<Runtime>)->Self{Self{network:Default::default(),auth:Default::default(),inventory:InventoryService::new(runtime.clone()),activities:ActivityService::new(runtime),world:Default::default(),telemetry:Default::default()}}pub fn dispatch(&mut self,p:Packet)->DispatchResult{let started=Instant::now();self.telemetry.request_log.push(format!("packet session={} opcode={:?}",p.session_id,p.opcode));self.telemetry.packet_traces.push(format!("{} bytes {:?}",p.payload.len(),p.direction));self.network.log.record(p.clone());let out=if p.opcode.is_none(){DispatchResult::UnknownOpcode}else{DispatchResult::Accepted};self.telemetry.service_timing_ms.push(("dispatch".into(),started.elapsed().as_millis()));out}pub fn record_session(&mut self,id:&str,event:&str){self.telemetry.session_history.push(format!("{id}:{event}"));}pub fn start(&self){tracing::info!("server runtime ready; protocol handlers remain research-only")}}
#[cfg(test)]mod tests{use super::*;#[test]fn unknown_packets_are_not_fabricated(){let db=Arc::new(Runtime::open(":memory:").unwrap());let mut r=ServerRuntime::new(db);let p=destiny_network::decode(vec![1,2]);assert!(matches!(r.dispatch(p),DispatchResult::UnknownOpcode));}}
